// Intended function: enforce ability availability deterministically while leaving damage/effect/world mutation to downstream authoritative systems.
#include "gameplay/AbilitySystem.hpp"
#include <algorithm>
namespace elysium{void AbilitySystem::registerDefinition(AbilityDefinition d){defs_[d.abilityId]=d;}void AbilitySystem::grant(std::uint64_t a,std::uint64_t id){if(!defs_.contains(id))return;auto i=std::find_if(runtime_.begin(),runtime_.end(),[&](auto&r){return r.actorId==a&&r.abilityId==id;});if(i==runtime_.end())runtime_.push_back({a,id,0,defs_[id].maxCharges});}void AbilitySystem::tick(float dt){for(auto&r:runtime_)r.cooldownRemaining=std::max(0.f,r.cooldownRemaining-dt);}std::optional<AbilityActivation>AbilitySystem::tryActivate(std::uint64_t a,std::uint64_t id,std::uint64_t t,std::uint64_t addr,float e){auto d=defs_.find(id);if(d==defs_.end()||e<d->second.energyCost)return std::nullopt;auto r=std::find_if(runtime_.begin(),runtime_.end(),[&](auto&x){return x.actorId==a&&x.abilityId==id;});if(r==runtime_.end()||r->cooldownRemaining>0||!r->charges)return std::nullopt;--r->charges;r->cooldownRemaining=d->second.cooldownSeconds;if(!r->charges&&d->second.maxCharges==1)r->charges=1;return AbilityActivation{a,id,t,addr,d->second.energyCost};}}
